CREATE OR REPLACE FUNCTION public.fn_assignee_added_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  pro_name text;
  agency_id uuid;
begin
  select coalesce(full_name, 'ekibimizden bir profesyonel') into pro_name
    from public.profiles where id = new.professional_id;
  select professional_id into agency_id
    from public.conversations where id = new.conversation_id;

  insert into public.messages (conversation_id, sender_id, message_type, body)
  values (new.conversation_id, agency_id, 'system',
          pro_name || ' talebinizle ilgilenmek üzere eklendi.');
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.fn_assignee_removed_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  remaining int;
  agency_id uuid;
begin
  select count(*) into remaining
    from public.conversation_assignees
    where conversation_id = old.conversation_id;

  if remaining = 0 then
    select professional_id into agency_id
      from public.conversations where id = old.conversation_id;
    insert into public.messages (conversation_id, sender_id, message_type, body)
    values (old.conversation_id, agency_id, 'system',
            'Talebiniz yeniden ajans tarafından yürütülecek.');
  end if;
  return old;
end $function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  user_role TEXT;
  user_full_name TEXT;
  user_company_name TEXT;
  user_phone TEXT;
  user_city_id INT;
  user_kvkk TIMESTAMPTZ;
  user_approval public.profile_approval_status;
  user_approved_at TIMESTAMPTZ;
BEGIN
  user_role := COALESCE(NEW.raw_user_meta_data->>'role', 'client');
  user_full_name := COALESCE(NEW.raw_user_meta_data->>'full_name', '');
  user_company_name := NEW.raw_user_meta_data->>'company_name';
  user_phone := NEW.raw_user_meta_data->>'phone';
  user_city_id := NULLIF(NEW.raw_user_meta_data->>'city_id', '')::INT;

  IF (NEW.raw_user_meta_data->>'kvkk_approved') = 'true' THEN
    user_kvkk := now();
  ELSE
    user_kvkk := NULL;
  END IF;

  -- Rol normalize
  user_role := CASE
    WHEN user_role IN ('customer', 'müşteri', 'musteri')        THEN 'client'
    WHEN user_role IN ('corporate', 'kurumsal')                  THEN 'business'
    WHEN user_role IN ('pro', 'profesyonel')                     THEN 'professional'
    WHEN user_role IN ('ajans')                                  THEN 'agency'
    WHEN user_role IN ('professional', 'client', 'business', 'agency')
                                                                  THEN user_role
    ELSE 'client'
  END;

  -- Onay durumu: client onaysız (approved), diğerleri pending
  IF user_role = 'client' THEN
    user_approval := 'approved';
    user_approved_at := now();
  ELSE
    user_approval := 'pending';
    user_approved_at := NULL;
  END IF;

  INSERT INTO public.profiles (
    id, email, full_name, role, company_name, phone, city_id,
    kvkk_approved_at, approval_status, approved_at
  )
  VALUES (
    NEW.id, NEW.email, user_full_name, user_role, user_company_name,
    user_phone, user_city_id, user_kvkk, user_approval, user_approved_at
  );

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.on_application_insert_notify_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  owner_id UUID;
  applicant_name TEXT;
  listing_title TEXT;
BEGIN
  SELECT l.creator_id, l.title INTO owner_id, listing_title
  FROM listings l WHERE l.id = NEW.listing_id;

  SELECT p.full_name INTO applicant_name
  FROM profiles p WHERE p.id = NEW.applicant_id;

  INSERT INTO notifications (user_id, type, body, link)
  VALUES (
    owner_id,
    'message',
    COALESCE(applicant_name, 'Bir profesyonel') || ' ilanına başvurdu: ' ||
      COALESCE(LEFT(listing_title, 60), 'İlan'),
    '/ilanlar/' || NEW.listing_id
  );

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.on_application_status_change_notify_applicant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  notif_body TEXT;
  listing_title TEXT;
BEGIN
  -- Status değişimi olmadıysa atla
  IF OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;

  -- Sadece bu status'lerde bildirim at
  IF NEW.status NOT IN ('shortlisted', 'accepted', 'rejected') THEN
    RETURN NEW;
  END IF;

  -- Profesyonel kendi başvurusunu withdraw ediyorsa kendine bildirim atma
  -- (zaten withdraw yukarıdaki listede yok ama defensive)

  SELECT l.title INTO listing_title
  FROM listings l WHERE l.id = NEW.listing_id;

  notif_body := 'Başvurun ' ||
    CASE NEW.status
      WHEN 'shortlisted' THEN 'kısa listeye alındı: '
      WHEN 'accepted' THEN 'kabul edildi 🎉: '
      WHEN 'rejected' THEN 'reddedildi: '
    END ||
    COALESCE(LEFT(listing_title, 60), 'İlan');

  NEW.responded_at := now();

  INSERT INTO notifications (user_id, type, body, link)
  VALUES (
    NEW.applicant_id,
    'message',
    notif_body,
    '/basvurularim'
  );

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.on_quote_responded_notify_professional()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  customer_name TEXT;
  notif_body TEXT;
BEGIN
  -- Sadece müşteri onaylar/reddederse profesyonele bildir
  IF NEW.status NOT IN ('accepted', 'declined') THEN
    RETURN NEW;
  END IF;
  IF OLD.status != 'pending' THEN
    RETURN NEW;
  END IF;

  SELECT p.full_name INTO customer_name
  FROM conversations c
  JOIN profiles p ON p.id = c.customer_id
  WHERE c.id = NEW.conversation_id;

  notif_body := COALESCE(customer_name, 'Müşteri') || ' teklifini ' ||
    CASE NEW.status
      WHEN 'accepted' THEN 'onayladı 🎉'
      WHEN 'declined' THEN 'reddetti'
    END;

  INSERT INTO notifications (user_id, type, body, link)
  VALUES (
    NEW.sender_id,
    'message',
    notif_body,
    '/mesajlar/' || NEW.conversation_id
  );

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_blog_posts_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_listing_published_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- İlan ilk kez published'a geçiyorsa published_at'i şimdiye set et
  IF NEW.status = 'published' AND (OLD.status IS NULL OR OLD.status != 'published') THEN
    NEW.published_at := now();
  END IF;

  -- expires_at boşsa ve published olduysa, 30 gün otomatik süre koy
  IF NEW.status = 'published' AND NEW.expires_at IS NULL THEN
    NEW.expires_at := now() + interval '30 days';
  END IF;

  RETURN NEW;
END;
$function$

